package com.financialcoach.auth;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;
import org.springframework.security.crypto.argon2.Argon2PasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;

/**
 * The demo users' hashes were generated by the Python backend (argon2-cffi, m=65536, t=3, p=4).
 * Spring must verify them with the parameters embedded in each hash, even though it creates new
 * hashes with different defaults. Hashes copied from db/dev/R__dev_seed.sql.
 */
class PasswordHashCompatibilityTest {

    private static final String CLIENT_HASH =
            "$argon2id$v=19$m=65536,t=3,p=4$3ukyRGtZ0bZEcqOlfZkipQ$q2+wYdOo1pubazJGmO/H1SkYiKXVRJmVU6lOsmQXynk";
    private static final String ADMIN_HASH =
            "$argon2id$v=19$m=65536,t=3,p=4$NYNR0YPxnuJNXzAcJy5pPw$WIELIsChcehPhl4wiiT+7UpShQy/ygonsSJhd2d2vME";

    private final PasswordEncoder encoder = Argon2PasswordEncoder.defaultsForSpringSecurity_v5_8();

    @Test
    void verifiesHashesCreatedByPythonArgon2() {
        assertThat(encoder.matches("ClientPass123!", CLIENT_HASH)).isTrue();
        assertThat(encoder.matches("AdminPass123!", ADMIN_HASH)).isTrue();
    }

    @Test
    void rejectsWrongPasswords() {
        assertThat(encoder.matches("ClientPass123", CLIENT_HASH)).isFalse();
        assertThat(encoder.matches("ClientPass123!", ADMIN_HASH)).isFalse();
    }
}
